//go:build ignore

// Standalone legacy dictionary check. No diameterkit imports or generated bytes.
package main

import (
	"bytes"
	"encoding/hex"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/ctrlzy/go-diameter/v4/diam"
	"github.com/ctrlzy/go-diameter/v4/diam/datatype"
	"github.com/ctrlzy/go-diameter/v4/diam/dict"
)

func must(err error) {
	if err != nil {
		panic(err)
	}
}
func load(name string) []byte {
	b, e := os.ReadFile(filepath.Join(os.Args[1], name+".hex"))
	must(e)
	b, e = hex.DecodeString(strings.Join(strings.Fields(string(b)), ""))
	must(e)
	return b
}
func check(a *diam.AVP) {
	if a.VendorID == 10415 {
		switch a.Code {
		case 3102, 3316, 3320, 3324:
			g, ok := a.Data.(*diam.GroupedAVP)
			if !ok {
				panic("group type")
			}
			for _, c := range g.AVP {
				check(c)
			}
		case 3325:
			if _, ok := a.Data.(datatype.OctetString); !ok {
				panic("legacy HSS-ID type changed")
			}
		case 3326, 3327:
			if _, ok := a.Data.(datatype.UTF8String); !ok {
				panic("URI type")
			}
		}
	} else if a.VendorID == 0 && a.Code == 1 {
		if _, ok := a.Data.(datatype.UTF8String); !ok {
			panic("User-Name type")
		}
	} else if a.Code == 3327 {
		if _, ok := a.Data.(datatype.Unknown); !ok {
			panic("wrong-vendor shadow")
		}
	}
}
func main() {
	if len(os.Args) != 2 {
		panic("fixture directory required")
	}
	for _, name := range []string{"v21-ims-rdr-r", "v21-ims-rdr-a", "v21-ims-rdr-f", "n26-rdr-username-text", "n26-rdr-hssid-nested", "n26-rdr-originuri", "n27-rdr-uri3327", "b32-no-uri", "b32-dup-uri", "b32-dup-group", "b32-hssid5", "b32-hssid16", "b32-hssid6", "b32-both-ids", "b32-msisdn-only", "b32-uri-params", "b32-uri-escaped", "b32-uri257", "b32-wrong-vendor", "b32-rda-5001"} {
		raw := load(name)
		m, e := diam.ReadMessage(bytes.NewReader(raw), dict.Default)
		must(e)
		if m.Header.ApplicationID != 16777312 || m.Header.CommandCode != 8388649 || m.Header.HopByHopID != 0x21210004 || m.Header.EndToEndID != 0x31310004 {
			panic("original pair header")
		}
		session := false
		for _, a := range m.AVP {
			check(a)
			if a.Code == 263 {
				session = string(a.Data.Serialize()) == "isg.example;21;4"
			}
		}
		if !session {
			panic("original pair session")
		}
		out, e := m.Serialize()
		must(e)
		if !bytes.Equal(raw, out) {
			panic("reencode")
		}
		fmt.Printf("PASS %s (%d bytes): original pair header/session, Grouped/UTF8 URI and exact reencode; legacy nested HSS-ID OctetString and semantic counterexamples are not conformance\n", name, len(raw))
	}
}
